UPDATE `services` SET `body` = '<h2>Fenêtre de Toit VELUX</h2><h4>Fenêtres de Toit Velux</h4><p>Laissez entrer lumière et air frais avec les fenêtres VELUX.</p>' WHERE `slug` = 'fenetre-de-toit-velux';
UPDATE `services` SET `body` = '<h3>Extension, Rénovation et Construction de Charpente</h3><p>Vous êtes propriétaire d''une maison ancienne ou récente et souhaitez faire agrandir votre lieu de vie ? Besoin de faire rénover votre demeure ? Faites confiance à Aertoit Couverture.</p><p>Spécialiste des travaux de couverture, notre équipe de professionnels intervient pour tous vos travaux d''extension ou de rénovation de votre charpente en bois.</p><p>La rénovation de votre charpente permet entre autre de restaurer votre bâtiment, et d''agrandir ou de surélever votre toiture.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Les Avantages d''Aertoit Couverture</h3><p>Une équipe de charpentiers passionnés à votre service.</p><p>Travail artisanal et sans aucune sous-traitance.</p><p>Accompagnement sur-mesure dans le choix des matériaux.</p><p>Respect de délais annoncés lors du devis.</p><p>Propreté irréprochable du début à la fin des travaux.</p><p>Résultats exceptionnels à chaque fois !</p><h3>Nous Intervenons sur TOUS Types de Chantiers !</h3><p>Travaux sur construction neuve.</p><p>Travaux pour agrandissement d’existant</p><p>Travaux de réparation, confortement ou renforcement d’existant</p><p>Travaux d’habillage de façades sur ossature bois.</p><p>L’ensemble des travaux de charpente bois sont réalisés par le personnel de l’entreprise sans faire appel à des entreprises sous-traitantes et/ou intérimaires.</p><p>Nos locaux ont une surface dédiée à ce type de travaux, entre autres un emplacement nous permettant de réaliser les épures échelle 1 au sol, puis de procéder au tracé, à la taille des différents éléments et des assemblages traditionnels.</p>' WHERE `slug` = 'travaux-de-charpente';
UPDATE `services` SET `body` = '<h3>Évitez les infiltrations d''eau : Travaux d''étanchéité pour votre toiture</h3><p>Le toit terrasse est la pièce extérieure dont la plupart des propriétaires raffolent grâce à l''espace supplémentaire offert par cette surface. Cependant, un toit plat doit être bien entretenu pour pérenniser son étanchéité et son côté agréable à vivre. Tous les problèmes liés à l''étanchéité doivent donc être bien anticipés, et pris en charge par une équipe de professionnels.</p><p>Notre Entreprise réalise les travaux nécessaires à la protection et de mise hors d’eau des toitures-terrasses, travaux spécifiques dits d’étanchéité. Notre personnel est formé et habilité à la mise en œuvre et à l’entretien de ces ouvrages et nous ne faisons pas appel à des entreprises sous-traitantes.</p><h3>Votre toiture terrasse en quelques mots</h3><p>Par définition, un toit terrasse a une pente très faible, voir inexistante. L''écoulement des eaux pluviales est donc plus compliqué que sur une toiture en pente. Ainsi, les travaux d''étanchéité doivent être réalisés de façon très précise par des professionnels. Une toiture plate doit également éviter les pertes de chaleur, ce qui peut entraîner rapidement un surcoût énergétique.</p><p>Afin de mettre en place une bonne étanchéité, et de protéger aussi bien votre toiture que le reste de la maison, nous procédons avec différentes techniques. Ces travaux d’étanchéité sont répertoriés suivant les supports à protéger, à savoir :</p><p>Terrasses bétonnées</p><p>Terrasses couvertes en bacs acier horizontaux</p><p>Terrasses sur ossatures bois</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Aertoit Couverture vous propose 3 techniques pour l''étanchéité de votre toiture</h3><h4>Étanchéité dite Multicouche</h4><h4>Étanchéité multicouche sur isolant haute densité﻿</h4><h4>Étanchéité multicouche sur isolant haute densité végétalisée</h4><h3>Nos Techniques d’Étanchéité</h3><p>Nous utilisons des techniques spécifiques en fonction des supports à protéger :</p><p>• Terrasses bétonnées</p><p>• Terrasses en bacs acier horizontaux</p><p>• Terrasses sur ossature bois</p><h3>Les Solutions d’Étanchéité Proposées par Aertoit Couverture</h3><p>• Étanchéité Multicouche : Solution classique offrant une étanchéité efficace.</p><p>• Étanchéité Multicouche sur Isolant Haute Densité : Assure une protection renforcée contre les intempéries.</p><p>• Étanchéité Multicouche Végétalisée : Combine isolation et esthétique avec une couverture végétale.</p><p>• Étanchéité avec Isolation Inversée : Technique où l’isolant est placé au-dessus de l’étanchéité, pour une durabilité accrue.</p><p>Avec Aertoit Couverture, bénéficiez d’une équipe de professionnels qualifiés, sans sous-traitance, pour une installation et un entretien durables de votre toit terrasse.</p>' WHERE `slug` = 'etancheite-de-toit-terrasse';
UPDATE `services` SET `body` = '<h3>Démoussage et Nettoyage de Gouttières : Protégez et Préservez Votre Toiture</h3><p>Un entretien régulier de la toiture est essentiel pour préserver l’intégrité de votre maison. Le démoussage et le nettoyage des gouttières sont des opérations incontournables pour assurer la longévité de vos matériaux de couverture et éviter des dommages potentiellement coûteux. Notre équipe professionnelle vous propose des solutions efficaces et durables pour entretenir votre toiture avec des produits performants, adaptés à chaque type de surface.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Démoussage de Toiture : Pourquoi est-ce Important ?</h3><p>Avec le temps, la mousse, les lichens et autres micro-organismes s’accumulent sur les toitures, en particulier dans les zones ombragées et humides. Ces végétaux retiennent l’humidité, ce qui peut fragiliser les matériaux de couverture et entraîner des infiltrations d''eau, des fissures ou encore la prolifération de champignons. Le démoussage régulier permet de prévenir ces problèmes et d''améliorer la durabilité de votre toiture.</p><p>Nous procédons à un enlèvement manuel des mousses épaisses et des lichens avec un balai et une brosse métallique, ce qui permet d''éliminer les plus gros dépôts. Ensuite, nous appliquons un traitement professionnel anti-mousse en deux étapes, à l''aide du produit DALEP 2100, qui agit en profondeur pour éliminer les micro-organismes et protéger la toiture.</p><h4>DALEP 2100 : Un Traitement Efficace et Durable</h4><p>Le produit DALEP 2100 est un fongicide professionnel reconnu pour son efficacité contre les champignons, algues, lichens, et autres micro-organismes. Sa formule concentrée permet un traitement curatif et préventif tout en imperméabilisant la toiture. Il convient à tous types de matériaux (tuiles, ardoises, béton, pierres, etc.), ce qui le rend polyvalent pour toutes les toitures.</p><h4>Caractéristiques clés du DALEP 2100</h4><p>Il traite et imperméabilise en une seule application, empêchant ainsi la réapparition des micro-organismes pendant une longue période.</p><p>Le produit s’utilise à partir du printemps, sous certaines conditions météorologiques, et nécessite une prévision d’environ 24 à 48 heures sans pluie après application pour être durable dans le temps en évitant ainsi un second passage.</p><p>Il n’abîme pas les matériaux et laisse respirer le support, assurant ainsi la protection à long terme de votre toiture.</p><p>Nous recommandons de traiter la toiture en profondeur, en veillant à ce que le produit traverse bien les végétaux pour atteindre et éliminer les germes au cœur des matériaux. Pour des cas de forte contamination, un traitement en deux passes peut être nécessaire pour des résultats optimaux.</p><h3>Nettoyage des Gouttières : Prévenir les Obstructions et Dégâts des Eaux</h3><p>Le bon état des gouttières est essentiel pour éviter les accumulations d’eau et les infiltrations qui peuvent causer des dommages structurels à votre maison. Des gouttières obstruées par des feuilles, des mousses et autres débris peuvent provoquer des débordements d’eau, détériorer les murs extérieurs et même endommager les fondations.</p><p>Notre service de nettoyage comprend :</p><p>L''enlèvement des débris manuellement, y compris le nettoyage complet de l’emboîture visible.</p><p>La mise en sac et l’évacuation de tous les déchets collectés.</p><p>Une vérification de l’état général des gouttières pour s''assurer de leur bon fonctionnement et prévenir tout risque futur.</p><p>Le nettoyage régulier des gouttières est recommandé pour maintenir un écoulement d''eau fluide et éviter tout risque d’infiltration. Cela prolonge également la durée de vie de vos installations et assure une protection optimale de votre habitation.</p>' WHERE `slug` = 'nettoyage-et-entretien-de-toiture';
UPDATE `services` SET `body` = '<h3>Pose de couverture en tuiles mécaniques et tuiles plates en terre cuite</h3><p>La toiture est un élément fondamental pour la protection et l’étanchéité de votre maison. Chez AERTOIT, nous mettons à votre service notre expertise en couverture pour la pose de tuiles mécaniques et tuiles plates en terre cuite. Ces matériaux, durables et esthétiques, apportent une solution fiable et respectueuse de l''environnement pour protéger efficacement votre habitation.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Les tuiles mécaniques en terre cuite</h3><h4>Qu’est-ce qu’une tuile mécanique ?</h4><p>Les tuiles mécaniques, ou tuiles à emboîtement, sont conçues pour s''emboîter parfaitement les unes aux autres. Ce système garantit une meilleure étanchéité et une pose plus rapide. Elles sont adaptées à tout type de toitures de faible ou importante pente et sont disponibles dans une large gamme de styles et de finitions.</p><h4>Avantages techniques des tuiles mécaniques</h4><p>Étanchéité renforcée : Grâce à leur système d''emboîtement, elles assurent une protection optimale contre les intempéries, notamment la pluie et le vent.</p><p>Facilité et rapidité de pose : Le système de rainures et de crans permet une installation plus rapide qu''avec d''autres types de tuiles.</p><p>Esthétique variée : Disponibles dans divers coloris et finitions grâce à plusieurs modèles, elles permettent de s’adapter aux styles architecturaux modernes comme traditionnels.</p><h4>Application des tuiles mécaniques en terre cuite</h4><p>Les tuiles mécaniques en terre cuite sont souvent utilisées pour des toitures dans des régions sujettes à des intempéries importantes, grâce à leur résistance naturelle à l''eau et aux vents. Elles sont également populaires dans les régions aux faibles pentes de toit, où une étanchéité parfaite est cruciale.</p><p>En plus de leur performance, ces tuiles sont fabriquées à partir d''argile naturelle, ce qui leur confère une excellente durabilité et un faible impact environnemental. Avec une durée de vie pouvant dépasser 50 ans, elles représentent un choix fiable et durable pour la couverture de votre toiture.</p><h3>Les tuiles plates en terre cuite</h3><h4>Qu’est-ce qu’une tuile plate ?</h4><p>Les tuiles plates sont l''une des formes les plus anciennes de tuiles en terre cuite. Elles sont généralement plus petites que les tuiles mécaniques et se posent par chevauchement et en quinconce. Ce type de tuile est particulièrement adapté aux toits à forte pente, offrant une esthétique classique et intemporelle.</p><h4>Avantages techniques des tuiles plates</h4><p>Adaptées aux toitures à forte pente : Grâce à leur conception, elles permettent de couvrir efficacement les toits avec des pentes importantes.</p><p>Grande résistance aux intempéries : Les tuiles plates, fabriquées en terre cuite, sont particulièrement résistantes au gel et aux conditions climatiques difficiles.</p><p>Durabilité exceptionnelle : Avec une durée de vie pouvant dépasser 100 ans, elles constituent un investissement à long terme.</p><p>Esthétique traditionnelle : Les tuiles plates apportent un charme authentique, souvent privilégié pour les bâtiments historiques ou les constructions de caractère.</p><h4>Application des tuiles plates en terre cuite</h4><p>Les tuiles plates en terre cuite sont particulièrement prisées pour leur aspect traditionnel et leur solidité. Elles sont souvent utilisées pour des toitures dans les zones où les conditions climatiques peuvent être extrêmes, notamment en montagne ou dans les régions au climat froid. En raison de leur petite taille, la pose des tuiles plates nécessite une plus grande densité de tuiles par m², environ 60 unités/m², garantissant ainsi une couverture robuste et résistante au vent.</p><p>Leur pose exige un savoir-faire particulier, puisque chaque tuile doit être posée manuellement avec précision pour garantir l''étanchéité et la durabilité du toit.</p><h3>Techniques de pose</h3><h4>Pose des tuiles mécaniques</h4><p>Pour les tuiles mécaniques, la pose est relativement rapide grâce à leur système d''emboîtement. Ce type de pose réduit les risques d''erreurs, et les travaux peuvent être effectués rapidement tout en assurant une excellente étanchéité. Ce procédé est idéal pour les projets nécessitant une couverture fiable dans un délai plus court.</p><h4>Pose des tuiles plates</h4><p>La pose des tuiles plates est plus technique. Chaque tuile doit être soigneusement appliquée et fixée pour garantir que l''eau de pluie s’écoule correctement sans risque d’infiltration. Cette technique traditionnelle requiert une plus grande attention et un savoir-faire expert.</p><h3>Accessoires et finition</h3><p>Pour garantir une couverture parfaite et esthétique, nous fournissons tous les accessoires nécessaires à la pose de tuiles, tels que les tuiles faîtières, tuiles de rive, chatières et les conduits de ventilation. Ces éléments assurent une finition harmonieuse et une protection supplémentaire contre les intempéries.</p><h3>Pourquoi choisir des tuiles en terre cuite ?</h3><p>La terre cuite est un matériau naturel, durable et écologique. Les tuiles en terre cuite offrent de nombreux avantages :</p><p>Respect de l''environnement : Fabriquées à partir de matériaux naturels, elles sont recyclables et contribuent à une construction durable.</p><p>Résistance aux conditions climatiques : Que ce soit face aux intempéries, au gel ou aux UV, la terre cuite garantit une excellente résistance à l''usure du temps.</p><h3>Conclusion</h3><p>Chez AERTOIT, nous vous proposons une expertise complète pour la pose de vos toitures en tuiles mécaniques et plates en terre cuite. Que vous optiez pour l''efficacité des tuiles mécaniques ou l''authenticité des tuiles plates, nous vous garantissons un service de qualité, réalisé par des professionnels expérimentés, pour une toiture durable, esthétique et parfaitement adaptée à votre région et vos besoins.</p>' WHERE `slug` = 'couverture-en-tuiles';
UPDATE `services` SET `body` = '<h3>Pose de Couverture en Ardoises</h3><p>La couverture en ardoises est une solution reconnue pour sa durabilité, son esthétique et ses performances techniques. L''ardoise, matériau naturel, a été utilisée pendant des siècles pour recouvrir les toitures, notamment en raison de sa robustesse et de sa capacité à résister aux conditions climatiques les plus extrêmes. Que ce soit pour des constructions neuves ou des rénovations, l''ardoise apporte une touche d''élégance tout en assurant une protection efficace de la structure.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Propriétés et Avantages des Ardoises Naturelles</h3><h4>Qu''est-ce qu''une ardoise ?</h4><p>L’ardoise est un matériau naturellement incombustible, imputrescible et ingélif, ce qui signifie qu’elle ne se dégrade pas sous l’effet du gel, ne brûle pas et ne se décompose pas. Ces caractéristiques en font un choix idéal pour les régions soumises à des variations de température importantes ou des précipitations fréquentes. Sa résistance aux intempéries, associée à une grande longévité, permet de garantir une toiture durable, capable de protéger le bâtiment pendant plusieurs décennies sans nécessiter d’entretien majeur.</p><p>De plus, l’ardoise est un matériau écologique. Extraite directement des carrières naturelles, comme celle de San Pedro de Trones ou Armadilla en Espagne, elle nécessite très peu de transformation industrielle, ce qui réduit son impact environnemental.</p><h3>Techniques de Pose et Considérations Techniques</h3><p>La pose d’une toiture en ardoises demande un savoir-faire spécifique pour garantir son efficacité et sa longévité. Elle débute généralement par la partie inférieure de la toiture, avec la pose d’un doublis sur chanlatte. Les ardoises sont ensuite fixées soit par clouage sur voligeage, soit par accrochage au crochet sur un liteau. Cette dernière méthode est souvent préférée, car elle permet une meilleure résistance face au vent, aux infiltrations et à éventuel remaniage.</p><p>Il est essentiel de veiller à ce que le recouvrement des ardoises soit suffisant pour éviter les remontées d’eau. Cela est particulièrement crucial dans les régions exposées à des vents forts, où l’eau pourrait être poussée sous les ardoises par la pression du vent. De plus, pour obtenir une couverture homogène, il est recommandé d’adopter une technique régulière lors de la pose. Cela consiste à mélanger les ardoises de différentes palettes pour éviter les variations de teinte qui peuvent survenir avec des matériaux naturels.</p><h3>Ardoise Cupa 7 (35x25 cm)</h3><p>L''ardoise Cupa 7 est un matériau de couverture naturel de grande qualité, directement importé d''Espagne. Cette ardoise de forme rectangulaire, mesurant 35x25 cm, se distingue par sa couleur gris bleu foncé, qui apporte une touche d''élégance classique à tout type de bâtiment.</p><h4>Spécificités techniques et avantages</h4><p>Incombustibilité et résistance aux intempéries : L''ardoise Cupa 7 est incombustible, ce qui la rend extrêmement résistante aux incendies. En outre, elle est imputrescible, ce qui signifie qu''elle ne se dégrade pas sous l''effet de l''humidité. Enfin, elle est ingélive, c''est-à-dire qu''elle ne subit pas de dégradation sous l''effet du gel, un atout majeur dans les régions soumises à de grands écarts de température.</p><p>Utilisation polyvalente : Cette ardoise est adaptée à tout type de toiture, que ce soit dans le cadre d’une construction neuve ou d’une rénovation. Elle peut être posée sur des toitures avec une pente minimale de 25 %, ce qui la rend particulièrement efficace pour des rampants de 5,50 mètres de longueur ou plus.</p><p>Conforme aux normes : L''ardoise Cupa est conforme aux normes françaises et européennes, notamment le DTU 40.11, garantissant une pose conforme aux exigences techniques. Cela assure non seulement la qualité de la toiture, mais également sa durabilité sur le long terme.</p><h3>Ardoise Cupa Excellence 4 (32x22 cm)</h3><p>L''ardoise Cupa Excellence 4 est une autre variante haut de gamme, provenant de la carrière Armadilla à Benuza en Espagne. Cette ardoise naturelle référencée pour les monuments historiques, elle est arborée d’une teinte gris foncé avec des inclusions métalliques non oxydables, ce qui ajoute un caractère unique.</p><p>Matériau naturel et écologique : L''ardoise Cupa Excellence 4 est entièrement naturelle et bénéficie d''un processus d''extraction respectueux de l''environnement. Elle est écologique, avec un faible taux d''absorption d''eau (0,29 %) et une faible teneur en carbone libre (0,59 %), la rendant durable et résistante aux conditions climatiques les plus rudes.</p><p>Garantie longue durée : Ce type d’ardoise est assorti d’une garantie de 30 ans, gage de sa longévité et de sa résistance aux intempéries. Sa planéité régulière permet une mise en œuvre rapide et précise, sans nécessiter de tri préalable, ce qui simplifie grandement le travail sur le chantier.</p><p>Résistance mécanique : Avec un module de rupture de 58, cette ardoise est extrêmement robuste. Elle offre une résistance à la flexion et au cisaillement, ce qui est un atout majeur dans les environnements soumis à des pressions climatiques élevées (vents violents, chutes de neige).</p><h3>Conclusion</h3><p>Opter pour une couverture en ardoises, c’est choisir un matériau noble et durable, capable de protéger efficacement une habitation contre les intempéries tout en lui apportant une élégance intemporelle. L’ardoise la Cupa Excellence, elle offre des garanties de qualité conformes aux exigences françaises et européennes.</p><p>Grâce à leurs propriétés exceptionnelles, les ardoises naturelles restent une référence incontournable pour toute toiture soucieuse d’allier performance technique et esthétique raffinée.</p>' WHERE `slug` = 'couverture-en-ardoises';
UPDATE `services` SET `body` = '<h3>Couverture en Bac Acier : Solution Durable et Performante pour un toit en faible pente</h3><p>La couverture en Bac Acier est une option de choix pour les toitures industrielles, agricoles, commerciales, et même résidentielles à faible pente. Grâce à ses propriétés techniques et esthétiques, ce matériau offre une grande résistance aux intempéries tout en assurant une pose rapide et efficace.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Caractéristiques Techniques du Bac Acier</h3><p>Le Bac Acier est conçu à partir d''acier de haute qualité, tel que l''acier S320 GD, qui est conforme aux normes EN 10346 et NF P 34-310. Il est généralement disponible en deux épaisseurs principales : 0,63mm et 0,75mm. Ces variations permettent d''adapter la toiture aux exigences de résistance et de durabilité spécifiques à chaque projet.</p><p>Les bacs aciers sont également protégés par des revêtements anticorrosion, dont le revêtement galvanisé et le polyester (25µ ou 35µ), qui permettent une résistance optimale aux agressions extérieures comme l''humidité, la corrosion, et les UV. D''autres revêtements spécifiques peuvent être disponibles sur demande, selon vos besoins.</p><h3>Efficacité et Résistance Mécanique</h3><p>La toiture en Bac Acier se distingue par sa robustesse face aux charges mécaniques, qu''elles soient ascendantes (vent) ou descendantes (neige, pluie). La capacité de flexion du matériau, mesurée en daN/m², varie en fonction de l''épaisseur du bac et de la configuration des nervures (sommet de nervure, fond d’onde). Par exemple, avec une épaisseur de 0,75 mm, le Bac Acier offre une résistance à l’arrachement sur appuis de 566 daN/m et une capacité de flexion allant jusqu’à 161 m.daN/m.</p><p>Les tests de résistance réalisés selon la norme NF P 34-503 et le DTU 40-35 confirment que ce type de couverture est conforme aux exigences en matière de charges d’exploitation non pondérées et de charges ascendantes. Ces valeurs garantissent la sécurité et la stabilité de la toiture, même dans des conditions climatiques difficiles.</p><h3>Installation et Fixation</h3><p>L’installation du Bac Acier est simplifiée grâce à un système de fixation en sommet ou en fond de nervures. Pour assurer une meilleure répartition des charges, il est recommandé de fixer toutes les nervures ou d’opter pour un système de fixation alternée, selon les spécificités de la structure.</p><p>Le Bac Acier permet également une grande modularité en termes de portée et de configuration des travées (simple, double ou multiple). Les portées utiles varient en fonction de l''épaisseur du bac et du type de charge, assurant une flexibilité optimale pour tout type de projet. Par exemple, pour une épaisseur de 0,75 mm, les travées multiples supportent des charges allant jusqu’à 2,35 daN/m² sur une portée de 2,40 mètres.</p><h3>Avantages de la Toiture en Bac Acier</h3><p>Durabilité : Grâce à ses revêtements anticorrosion, le Bac Acier assure une longue durée de vie et nécessite peu d''entretien.</p><p>Légèreté : Comparé à d’autres matériaux, le Bac Acier est léger, ce qui facilite son transport et sa pose, tout en minimisant les charges sur la structure du bâtiment.</p><p>Résistance : Il résiste efficacement aux charges mécaniques et climatiques, qu''il s''agisse de vent, de neige ou de fortes pluies.</p><p>Rapidité de Pose : La simplicité de pose du Bac Acier permet de réduire les temps de chantier, avec des fixations rapides et une couverture uniforme.</p><h3>Options de Revêtements et Esthétiques</h3><p>Le Bac Acier offre également des options esthétiques grâce à des revêtements colorés en polyester, disponibles en plusieurs épaisseurs de protection (25µ ou 35µ). Cela permet non seulement de protéger la toiture, mais aussi de lui donner un aspect moderne et personnalisé en fonction des préférences architecturales.</p><h3>Spécification avec une isolation Intégrée</h3><p>Le Bac Acier peut être combiné avec des isolants incorporés, offrant ainsi une solution tout-en-un pour améliorer l''efficacité thermique de la toiture. Il est composé d''une double couche de tôle d''acier, entre lesquelles se niche un isolant autoportant de haute qualité comme par exemple avec la mousse polyuréthane ou de laine de roche ou de laine de verre, ce qui va réduire considérablement les pertes de chaleur ainsi que les ponts thermiques. Cette isolation permet de répondre aux exigences réglementaires en matière d''efficacité énergétique, tout en améliorant le confort à l''intérieur du bâtiment.</p><h3>Conclusion</h3><p>La couverture en Bac Acier se présente comme une solution de toiture robuste, durable, et performante, adaptée aussi bien aux bâtiments industriels qu''aux projets résidentiels. Grâce à ses caractéristiques techniques éprouvées, sa résistance aux intempéries et sa facilité de pose, le Bac Acier est un choix idéal pour assurer une protection efficace et esthétique à long terme. Que vous cherchiez à optimiser la durée de vie de votre toiture ou à accélérer vos travaux, cette solution vous garantit des résultats fiables et économiques. Pour en savoir plus sur les options disponibles et obtenir des conseils personnalisés, n’hésitez pas à nous contacter.</p>' WHERE `slug` = 'couverture-en-bac-acier';
UPDATE `services` SET `body` = '<h3>Laine de Verre : L''Isolant Léger et Efficace</h3><p>Vous recherchez une solution performante et durable pour l’isolation de votre maison ? Aertoit Couverture vous propose l’isolation par laine de verre ISOVER, un matériau léger et efficace, idéal pour isoler les combles perdus, les planchers et plafonds.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Laine de Verre ISOVER : Performance et Polyvalence</h3><p>La laine de verre ISOVER est réputée pour sa capacité à emprisonner l’air immobile, ce qui en fait un excellent isolant thermique. Grâce à sa structure poreuse, elle assure une isolation optimale tout en restant légère et facile à installer. Adaptée à diverses surfaces, elle s’ajuste parfaitement à vos besoins, que ce soit pour des combles perdus ou des travaux plus spécifiques.</p><h3>Les Avantages de la Laine de Verre</h3><p>Excellente performance thermique : Le coefficient de conductivité thermique (lambda) de la laine de verre se rapproche de celui de l’air sec immobile (λ = 0,030 W/(m.K)).</p><p>Résistance thermique (R) ajustable : Disponible en plusieurs épaisseurs pour une isolation adaptée à chaque projet, avec des valeurs R allant jusqu''à 10 m².K/W.</p><p>Isolation acoustique : En plus de l''isolation thermique, la laine de verre absorbe les bruits aériens et de chocs, assurant un confort sonore optimal.</p><p>Résistance au feu : Fabriquée à base de minéraux incombustibles, la laine de verre ne propage pas les flammes, garantissant une sécurité maximale pour votre habitation.</p><h3>Les Garanties Aertoit pour une Isolation de Qualité</h3><p>Avec Aertoit Couverture, vous bénéficiez d''une expertise reconnue et de produits certifiés ACERMI, garantissant une performance durable et conforme aux normes en vigueur. Nous vous accompagnons tout au long de votre projet pour vous offrir une isolation de qualité, adaptée à vos besoins.</p><p>Optez pour la laine de verre ISOVER avec Aertoit Couverture pour une isolation performante, durable et éligible aux aides de l’État.</p>' WHERE `slug` = 'solutions-d-isolation-laine-de-verre';
UPDATE `services` SET `body` = '<h3>Aertoit, Expert de l''Isolation par Laine de Roche</h3><p>Vous cherchez à optimiser l’isolation de votre maison ? Aertoit Couverture vous propose des solutions d’isolation performantes grâce à la laine de roche. Que ce soit pour une rénovation ou une construction neuve, notre équipe, spécialisée depuis plus de 25 ans, intervient rapidement pour améliorer votre confort thermique et acoustique.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Une Isolation Durable et Efficace</h3><p>La laine de roche est un matériaux naturel, fabriqué à partir de roche volcanique fondue. Elle offre une isolation optimale pour les combles, toitures inclinées, et murs creux, tout en assurant une excellente régulation de l''humidité et une résistance au feu.</p><h3>Les Avantages de la Laine de Roche</h3><p>Confort thermique garanti : La laine de roche conserve sa performance isolante dans le temps.</p><p>Matériaux respirant : Permet une bonne circulation de l''air, évitant ainsi l''humidité et les moisissures.</p><p>Isolation acoustique : Réduit les bruits extérieurs pour un confort supplémentaire.</p><p>Résistance au feu : Protège votre habitation grâce à une forte résistance aux températures élevées.</p><h3>Une Équipe de Professionnels à Votre Service</h3><p>Chez Aertoit Couverture, nous mettons à votre disposition notre savoir-faire artisanal et notre expérience pour des travaux d''isolation sans sous-traitance. Nous vous accompagnons dans le choix des matériaux et assurons une installation soignée et durable.</p><p>Pour chaque projet, nous garantissons un travail propre, dans le respect des délais annoncés, et un résultat à la hauteur de vos attentes.</p><p>Faites confiance à Aertoit Couverture pour une isolation de qualité, adaptée à vos besoins.</p>' WHERE `slug` = 'solutions-d-isolation-laine-de-roche';
UPDATE `services` SET `body` = '<h3>Optez pour l''Éco Isolation avec la Fibre de Bois</h3><p>Vous souhaitez une isolation à la fois écologique et performante pour votre maison ? Aertoit Couverture vous propose l''isolation en fibre de bois STEICO, un matériaux naturel et durable, idéal pour limiter les déperditions thermiques et améliorer votre confort acoustique.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Fibre de Bois STEICO : Une Solution Écologique et Performante</h3><p>L’isolation en fibre de bois STEICO est fabriquée à partir de bois issu de forêts gérées durablement. Ce matériau renouvelable et recyclable offre une excellente résistance thermique, adaptée aussi bien pour l’hiver que pour l’été. Les panneaux STEICOflex, souples et faciles à poser, sont disponibles en plusieurs épaisseurs pour répondre à tous les besoins d’isolation de vos combles, toitures, et murs.</p><h3>Les Avantages de la Fibre de Bois</h3><p>Performance thermique élevée : La fibre de bois assure une isolation efficace tout en stockant jusqu’à 85 kg de carbone par m², réduisant ainsi votre empreinte carbone.</p><p>Isolation phonique renforcée : Les panneaux STEICO absorbent les bruits, améliorant ainsi le confort acoustique de votre habitation.</p><p>Matériaux écologique : Fabriqué à partir de bois issu de forêts durables, la fibre de bois est une solution respectueuse de l’environnement.</p><h3>Aertoit : Expert de l''Isolation Responsable</h3><p>Les produits STEICO, certifiés ACERMI, sont reconnus pour leur qualité et leur durabilité. En plus de la fibre de bois, Aertoit Couverture propose d’autres isolants naturels comme la laine de roche, la laine de verre, le sarking et l''actis.</p><p>En optant pour l’isolation en fibre de bois STEICO avec Aertoit Couverture, vous bénéficiez d’une solution compétitive, éligible aux aides de l’État, pour un habitat plus confortable et écoresponsable.</p>' WHERE `slug` = 'solutions-d-isolation-sarking-fibre-de-bois';
UPDATE `services` SET `body` = '<h3>Optimisez l''Isolation de Votre Toiture avec le Sarking</h3><p>Vous souhaitez isoler efficacement votre toiture tout en préservant l''esthétique de votre maison ? Aertoit Couverture vous propose l’isolation par sarking, une solution idéale pour vos projets de rénovation ou de construction neuve. Cette technique, initialement développée pour les climats de montagne, garantit des performances thermiques et acoustiques exceptionnelles.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Performances Thermiques et Acoustiques Supérieures</h3><p>Le sarking consiste à poser des panneaux isolants rigides directement sur la charpente, réduisant ainsi les ponts thermiques et offrant une isolation continue. Adaptée à tous types de toitures, cette solution innovante permet une protection maximale tout en renforçant la durabilité de votre structure.</p><h3>Les Avantages du Sarking</h3><p>Légèreté : Les panneaux en mousse polyuréthane sont jusqu''à cinq fois plus légers que d''autres isolants, facilitant la manipulation et réduisant le besoin de renforcement de la charpente.</p><p>Faible épaisseur et légèreté : Avec une résistance thermique élevée (R > 6 m².K/W), les panneaux en polyuréthane ont une épaisseur comprise entre 13 cm et 24 cm, réduisant ainsi la surélévation de la toiture. Leur légèreté les rend également plus faciles à manipuler et à installer, offrant un avantage notable par rapport aux panneaux de sarking en fibre de bois, souvent plus lourds.</p><p>Résistance mécanique : Que vous soyez en plaine ou en montagne, les panneaux en PU offrent une excellente résistance à la compression, garantissant une installation durable.</p><p>Durabilité : L''isolation par l''extérieur protège la charpente en la maintenant dans le volume chauffé, prolongeant ainsi sa durée de vie.</p><h3>Une Isolation Performante et Durable avec Aertoit</h3><p>Chez Aertoit Couverture, nous utilisons des produits de qualité certifiés ACERMI et CE, garantis 10 ans. Nos solutions de sarking sont également éligibles aux aides de l''État pour la transition énergétique, comme le CITE.</p><p>Faites confiance à Aertoit Couverture pour une isolation sarking performante, durable et esthétique, parfaitement adaptée à vos besoins et à votre région.</p>' WHERE `slug` = 'solutions-d-isolation-sarking-polyurethane';
UPDATE `services` SET `body` = '<h3>Actis : L''Isolation Innovante pour un Confort Durable</h3><p>Vous recherchez une isolation performante qui combine étanchéité et confort thermique ? Aertoit Couverture vous propose les solutions d''isolation Actis, une référence en matière d''efficacité énergétique, disponible pour tous types de projets de rénovation ou de construction neuve.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Étanchéité et Performance Thermique en Une Seule Solution</h3><p>L’isolation Actis TRISO-TOITURE est un système innovant qui assure une isolation complète : thermique, phonique et une étanchéité à l’air et à l’eau, certifiée selon la norme NF EN 16012. Cette solution performante se compose de deux éléments complémentaires :</p><p>Triso-Hybrid’ : Isolant réflecteur avec pare-vapeur intégré.</p><p>Boost’R Hybrid’ : Isolant réflecteur respirant avec écran HPV intégré.</p><p>Ensemble, ces composants forment une enveloppe légère, flexible et facile à installer, garantissant une isolation de haute performance.</p><h3>Les Avantages de l''Isolation Actis</h3><p>Isolation thermique renforcée : Résistance thermique élevée (R > 6,20 m².K/W) pour une efficacité optimale hiver comme été.</p><p>Confort d’été : Jusqu’à 95 % des rayonnements infrarouges sont réfléchis pour limiter la chaleur.</p><p>Isolation phonique : Matériaux souples et étanches à l’air pour une atténuation des bruits extérieurs.</p><p>Étanchéité à l’eau et à l’air : Garantie d’une protection maximale contre les intempéries et les infiltrations.</p><h3>L''Expertise Aertoit au Service de Votre Confort</h3><p>Avec plus de 25 ans d’expérience, Aertoit Couverture vous accompagne dans vos projets d’isolation avec la gamme Actis. Nous nous engageons à vous offrir :</p><p>Un travail soigné, sans sous-traitance.</p><p>Des matériaux respectueux de l''air intérieur et sans fibres irritantes.</p><p>Un accompagnement personnalisé, adapté à vos besoins spécifiques.</p><p>Faites confiance à Aertoit Couverture pour une isolation Actis de haute qualité, qui allie confort et performance.</p>' WHERE `slug` = 'solutions-d-isolation-actis';
UPDATE `services` SET `body` = '<h4>Stores Occultants (Réf. DKL, DML, DSL) :</h4><p>Ces stores sont parfaits pour les chambres, garantissant une occultation optimale de 99,8 %. Grâce à leur design exclusif et à la finesse des profilés, ils préservent l’entrée de lumière lorsqu''ils sont remontés. Leur toile est certifiée Oeko-Tex®, sans substances nocives, et leur installation est simplifiée grâce au système Pick&Click breveté.</p><h4>Volets Roulants (Réf. SML, SSL) :</h4><p>Ils bloquent 95 % de la chaleur en été et augmentent l’isolation de 27 % en hiver. Ces volets offrent également une occultation totale et réduisent de 4 fois les bruits de pluie et de grêle. Fabriqués en aluminium résistant, ils dissuadent les effractions et s''intègrent discrètement à vos fenêtres de toit, garantissant confort et sérénité tout au long de l''année.</p><h4>Stores Extérieurs Pare-Soleil (Réf. MHL, MML, MSL) :</h4><p>Idéaux pour toutes les pièces, ces stores arrêtent jusqu''à 86 % de la chaleur tout en laissant entrer la lumière. Fabriqués en toile résille semi-transparente, ils protègent efficacement contre les UV et offrent une vue dégagée vers l''extérieur.</p><h4>Barre de Manœuvre VELUX</h4><p>La barre de manœuvre VELUX est un élément central dans la conception des fenêtres de toit, offrant une ergonomie optimale et une utilisation simplifiée. Placée en partie haute de la fenêtre, elle permet une ouverture facile et rapide, même lorsque des meubles ou obstacles se trouvent sous la fenêtre. Ce positionnement ingénieux maximise l’espace intérieur, tout en assurant une manipulation sécurisée et sans effort.</p><p>Polyvalence :</p><p>Que la fenêtre soit en position de rotation ou de projection, la barre de manœuvre facilite son utilisation au quotidien. Elle permet un contrôle précis de l’ouverture pour ajuster la ventilation en fonction des besoins.</p><p>Ventilation optimisée :</p><p>La barre de manœuvre intègre un clapet de ventilation, qui permet d’aérer la pièce sans avoir à ouvrir entièrement la fenêtre. Ce système permet de renouveler l’air intérieur tout en maintenant la sécurité et l’étanchéité de la fenêtre.</p><p>Design épuré :</p><p>Sa conception discrète s’intègre harmonieusement dans l’esthétique générale de la fenêtre, sans compromettre la lumière naturelle qui entre dans la pièce.</p><p>Sélectionnez le service souhaité</p><p>Charpente Traditionnelle</p><p>Nom Complet*</p><p>Adresse E-mail*</p><p>Téléphone*</p><p>Commune*</p><h3>Conclusion</h3><p>Ces accessoires VELUX, qu’il s’agisse de stores ou de volets roulants, sont conçus pour s’adapter à chaque type de fenêtre et répondent aux exigences les plus strictes en matière de performance énergétique, de confort et de sécurité.</p>' WHERE `slug` = 'accessoires-velux';
UPDATE `job_postings` SET `body` = '<p>07/08/2024</p><p>📍94240 L''Haÿ-les-Roses</p><p>📄 Alternance</p><p>🕐 Temps Plein</p><p>💸 2500 € / mois</p><p>🎓 BTS Gestion de la PME</p><p>💼 ≥ 1 an</p><h2>Description du Poste</h2><p>Vous serez responsable de la logistique administrative ainsi que du suivi client et de la gestion des équipes</p><p>Si ce profil correspond au vôtre et que vous avez les compétences requises, postulez pour rejoindre notre équipe motivée.</p><h2>Les Missions</h2><ul><li>Gestion et supervision des chantiers</li><li>Relation client et reporting</li><li>Réalisation des travaux de couvertures</li><li>Gestion du matériel et de son équipe</li><li>Contrôle qualité, sécurité et conformité</li><li>Encadrer et former des équipes moins expérimentées</li></ul><h2>Profil Recherché</h2><h4>Qualités Personelles</h4><p>Autonomie et sens de l''initiative</p><p>Précision et rigueur dans l''exécution des tâches</p><p>Esprit d''équipe et capacité à encadrer des équipes</p><h4>Compétences Techniques</h4><ul><li>Maîtrise des différentes techniques de couverture et des matériaux couramment utilisés</li><li>Connaissance approfondie des normes de sécurité liées au travail en hauteur</li><li>Capacité à lire et interpréter des plans et des croquis techniques</li></ul><h4>Avantages</h4><p>Mutuelle d''entreprise</p><p>Participation aux frais de transport</p><p>Formations continues et possibilités d''évolution</p><p>Primes individuelles semestrielles</p><p>Activités extraprofessionnelles (repas de fin d''année, séminaires)</p><p>Accès à des places pour des événements sportifs (PSG Parc des Princes)</p><h4>Conditions de Travail</h4><p>Prêt à rejoindre une entreprise dynamique ?</p><h2>Nos attendons votre CV avec impatience !</h2><p>Démarrez votre candidature dès maintenant en remplissant le formulaire de recrutement</p>' WHERE `slug` = 'assistant-polyvalent';
UPDATE `job_postings` SET `body` = '<p>06/08/2024</p><p>📍94240 Val-de-Marne</p><p>📄 CDI</p><p>🕐 Temps Plein</p><p>💸 2300 - 2900 € net / mois + primes</p><p>🎓 CAP / BP ou autres</p><p>💼 ≥ 10 ans</p><h2>Description du Poste</h2><p>Vous serez responsable de la réalisation de travaux de couverture en neuf et en rénovation, incluant la pose de matériaux variés tels que tuiles, ardoises, zinc, bac acier, plomb, etc.</p><p>Si ce profil correspond au vôtre et que vous avez les compétences requises, postulez pour rejoindre notre équipe motivée.</p><h2>Les Missions</h2><ul><li>Gestion et supervision des chantiers</li><li>Relation client et reporting</li><li>Réalisation des travaux de couvertures</li><li>Gestion du matériel et de son équipe</li><li>Contrôle qualité, sécurité et conformité</li><li>Encadrer et former des équipes moins expérimentées</li></ul><h2>Profil Recherché</h2><h4>Qualités Personelles</h4><p>Autonomie et sens de l''initiative</p><p>Aptitude à planifier les travaux et à gérer les priorités avec précision</p><p>Esprit d''équipe et capacité à encadrer des équipes (leadership)</p><p>Bon relationnel pour assurer une communication efficace avec l’équipe</p><p>et les clients.</p><h4>Compétences Techniques</h4><ul><li>Maîtrise des différentes techniques de couverture et des matériaux couramment utilisés</li><li>Connaissance approfondie des normes de sécurité liées au travail en hauteur</li><li>Capacité à lire et interpréter des plans et des croquis techniques</li></ul><h4>Avantages</h4><p>Mutuelle d''entreprise</p><p>Participation aux frais de transport</p><p>Formations continues et possibilités d''évolution</p><p>Primes individuelles semestrielles</p><p>Activités extraprofessionnelles (repas de fin d''année, séminaires)</p><p>Accès à des places pour des événements sportifs (PSG Parc des Princes)</p><h4>Conditions de Travail</h4><p>Travail principalement en extérieur et en hauteur</p><p>Déplacements possibles sur différents chantiers</p><p>Port des équipements de protection individuelle obligatoire</p><p>Prêt à rejoindre une entreprise dynamique ?</p><h2>Nos attendons votre CV avec impatience !</h2><p>Démarrez votre candidature dès maintenant en remplissant le formulaire de recrutement</p>' WHERE `slug` = 'couvreur-experimente';
UPDATE `job_postings` SET `body` = '<p>21/10/2024</p><p>📍94240 Val-de-Marne</p><p>📄 CDD avec possibilité de CDI</p><p>🕐 Temps Plein</p><p>💸 1900 - 2400 € net / mois + primes</p><p>🎓 CAP / BP ou autres</p><p>💼 ≥ 5 ans</p><h2>Description du Poste</h2><p>Vous accompagnerez votre chef d’équipe pour la réalisation de travaux de couverture en neuf et en rénovation, incluant la pose de matériaux variés tels que tuiles, ardoises, zinc, bac acier, plomb, etc.</p><p>Si ce profil correspond au vôtre et que vous avez les compétences requises, postulez pour rejoindre notre équipe motivée.</p><h2>Les Missions</h2><ul><li>Gestion et supervision des chantiers</li><li>Relation client et reporting</li><li>Réalisation des travaux de couvertures</li><li>Gestion du matériel et de son équipe</li><li>Contrôle qualité, sécurité et conformité</li><li>Encadrer et former des équipes moins expérimentées</li></ul><h2>Profil Recherché</h2><h4>Qualités Personelles</h4><p>Autonomie et sens de l''initiative</p><p>Précision et rigueur dans l''exécution des tâches</p><p>Esprit d''équipe et capacité à encadrer des équipes</p><h4>Compétences Techniques</h4><ul><li>Maîtrise des différentes techniques de couverture et des matériaux couramment utilisés</li><li>Connaissance approfondie des normes de sécurité liées au travail en hauteur</li><li>Capacité à lire et interpréter des plans et des croquis techniques</li></ul><h4>Avantages</h4><p>Mutuelle d''entreprise</p><p>Participation aux frais de transport</p><p>Formations continues et possibilités d''évolution</p><p>Primes individuelles semestrielles</p><p>Activités extraprofessionnelles (repas de fin d''année, séminaires)</p><p>Accès à des places pour des événements sportifs (PSG Parc des Princes)</p><h4>Conditions de Travail</h4><p>Travail principalement en extérieur et en hauteur</p><p>Déplacements possibles sur différents chantiers</p><p>Port des équipements de protection individuelle obligatoire</p><p>Prêt à rejoindre une entreprise dynamique ?</p><h2>Nos attendons votre CV avec impatience !</h2><p>Démarrez votre candidature dès maintenant en remplissant le formulaire de recrutement</p>' WHERE `slug` = 'couvreur-qualifie';
UPDATE `blog_posts` SET `body` = '<p>Plus besoin de déserter les chambres sous les toits si l’isolation est bonne ! Avec les vagues de chaleur de plus en plus fréquentes, bien isoler sa maison devient indispensable. Parmi les solutions les plus performantes et respectueuses de l’environnement, la fibre de bois se distingue par ses qualités exceptionnelles. C’est aujourd’hui l’un des meilleurs isolants pour préserver votre confort intérieur en été.</p><h4>Qu’est-ce que la fibre de bois ?</h4><p>La fibre de bois est un matériau isolant naturel fabriqué à partir de résidus de bois issus de forêts gérées durablement. Disponible en panneaux souples et rigides, elle convient parfaitement à l’isolation des toitures, combles, murs et planchers.</p><h4>Une isolation thermique redoutable contre la chaleur</h4><p>Le principal atout de la fibre de bois réside dans son excellent déphasage thermique. Ce terme désigne le temps que met la chaleur extérieure à traverser l’isolant. Plus ce temps est long, plus l’intérieur reste frais. La fibre de bois peut atteindre jusqu’à 12 heures de déphasage, contre 4 à 6 heures pour un isolant de type polyuréthane.</p><p>Ce pouvoir isolant élevé permet de maintenir une température agréable dans la maison, même lors des journées les plus chaudes.</p><h4>Une isolation acoustique efficace</h4><p>En plus de ses performances thermiques, la fibre de bois assure un très bon confort acoustique. Elle atténue les bruits extérieurs et contribue à un environnement intérieur plus paisible.</p><h4>Une solution écologique et durable</h4><p>Matériau biosourcé, renouvelable et recyclable</p><p>Sans composants nocifs ni fibres irritantes</p><p>Produit à faible empreinte carbone, capable de stocker du CO₂</p><p>C’est un choix responsable, autant pour le confort que pour la planète.</p><h4>Pourquoi choisir Aertoit pour vos travaux d’isolation ?</h4><p>Chez Aertoit, nous posons des panneaux STEICO, reconnus pour leur qualité et leur performance. Certifiés ACERMI, ils répondent aux plus hauts standards du marché. Nos équipes interviennent en Île-de-France it vous accompagnent à chaque étape de votre projet, du diagnostic à la pose.</p><h4>Conclusion</h4><p>La fibre de bois est une solution d’isolation naturelle, performante et durable. Elle vous garantit une protection optimale contre la chaleur estivale tout en valorisant votre habitat. Isoler aujourd’hui, c’est anticiper les canicules de demain.</p><p>Demandez dès maintenant votre devis à Aertoit Couverture pour un été au frais en toute sérénité.</p>' WHERE `slug` = 'fibre-de-bois-isolant-naturel-ideal-contre-la-canicule';
UPDATE `blog_posts` SET `body` = '<p>Quand on regarde une maison, on admire souvent sa façade ou son architecture. Pourtant, l’élément le plus crucial pour la longévité du bâtiment se trouve au-dessus de nos têtes : la toiture. Derrière cette structure protectrice se cache un artisan passionné, « le couvreur ».</p><p>Chez AERTOIT, nous profitons de ce mois de mai pour mettre en lumière ce métier de précision, véritable pilier de l’habitat.</p><h4>Un métier indispensable mais encore trop méconnu</h4><p>Le couvreur est le gardien de votre confort. Que ce soit pour une construction neuve ou une rénovation, son rôle est vital : mettre un bâtiment « hors d’eau ». Sans lui, pas d’étanchéité, pas d’isolation efficace, et une structure exposée aux dégradations.</p><p>Pourquoi en parler maintenant ? Lors des beaux jours de printemps, alors que les chantiers de rénovation reprennent de plus belle après l''hiver, il est essentiel de rappeler que la couverture est une discipline complexe. Malgré une forte demande, le secteur connaît un recrutement en tension : valoriser ce savoir-faire et le transmettre, c''est aussi susciter des vocations pour un métier d''avenir.</p><h4>Les missions journalières du couvreur : une bonne organisation</h4><p>Le quotidien d''un couvreur chez AERTOIT est rythmé par une grande diversité de tâches :</p><p>Pose, entretien et réparation : Nos équipes sont habilités à intervenir par des réalisations de toiture complète ou partiel, ainsi que pour les entretiens annuels sur les différents points faibles d’une toiture vieillissante.</p><p>Maîtrise des matériaux : Nos couvreurs façonnent le zinc, posent les tuiles, les ardoises ou le bac acier avec précision, maîtrisent l’étanchéité, installent différents types d’isolants thermiques en surtoiture et créent ou remplacent des fenêtres de toit de la marque Velux.</p><p>Sécurité nécessaire : Travailler sur les toits demande une rigueur totale dans la gestion du risque. L''installation d''échafaudages, de harnais et de lignes de vie fait partie intégrante du métier pour garantir la sécurité des équipes et du chantier.</p><p>Formation : L’entreprise met un point d’honneur à transmettre aux jeunes cette passion à travers une formation qui commence au CAP, en passant par une mention puis un BP.</p><h4>Une expertise technique polyvalente</h4><p>Être couvreur, c’est être un technicien confirmé. Cela demande :</p><p>Une connaissance approfondie des matériaux : Savoir comment le zinc réagit aux variations de température ou quelle tuile est la mieux adaptée à la pente du toit.</p><p>La maîtrise d''outils spécialisés : Façonner à l’aide d’une plieuse à zinc avec agilité, utilisation du fer et manier de outils de découpe.</p><h4>Les qualités humaines : la force du terrain</h4><p>Au-delà de la technique, le métier exige des qualités humaines solides :</p><p>L’adaptation : Le couvreur travaille en extérieur. Il doit composer avec le vent, le soleil, la pluie ou le froid, tout en restant concentré.</p><p>L''organisation et la rigueur : Une erreur de quelques centimètres dans la pose peut compromettre une partie de l''étanchéité de votre maison.</p><p>L’esprit d’équipe : Sur un toit, la solidarité et la communication sont indispensables. Chez AERTOIT, cette cohésion est le moteur de notre réussite.</p><h4>Les évolutions du métier : technologie et innovation</h4><p>Le métier de couvreur évolue avec son temps. Loin de l''image d''un artisanat figé, il intègre aujourd''hui des technologies modernes :</p><p>Des machines performantes : Chez AERTOIT, nous utilisons des outils de façonnage et des machines performantes qui facilitent les tâches pénibles et augmentent la précision de notre travail.</p><p>Sécurité renforcée : Les équipements de protection individuelle (EPI) sont de plus en plus ergonomiques, garantissant une meilleure mobilité tout en assurant une protection optimale à travers la pose d’échafaudage. Technique de pose durable : tubulaire et multidirectionnel</p><h4>AERTOIT valorise ses experts couvreurs</h4><p>Chez AERTOIT, nous sommes fiers de nos équipes. Chaque chantier est le reflet de l’expertise, de la passion de nos couvreurs et d’une bonne communication avec nos clients. Reconnaître la technicité de leur travail, c''est respecter la valeur de votre patrimoine immobilier.</p><p>Faire appel à AERTOIT, c’est confier votre toit à des professionnels expérimentés qui allient tradition du métier et modernité des techniques. Parce qu''une maison sûre commence toujours par une toiture impeccable.</p><p>Pour votre toiture besoin d''un diagnostic gratuit ou d''un devis : Contactez AERTOIT</p>' WHERE `slug` = 'le-metier-de-couvreur-savoir-faire-technique';
UPDATE `blog_posts` SET `body` = '<h4>Zinc ou PVC : deux possibilités</h4><p>Quand on parle des gouttières et des éléments de toiture, beaucoup pensent que “c’est juste un détail" mais c’est une erreur.</p><p>Une gouttière mal choisie ou mal posée c’est souvent :</p><p>des fuites,</p><p>des façades abîmées,</p><p>et des réparations qu’on aurait préféré éviter.</p><p>Alors ZINC ou PVC ?</p><p>Chez AERTOIT, on essayera toujours de vous conseiller au mieux.</p><h4>À quoi servent vraiment les gouttières et pourquoi on y prête rarement attention</h4><p>Les gouttières et éléments de zinguerie ne sont pas là seulement pour décorer (même si le visuel à son importance).</p><p>Leur mission est simple mais cruciale :</p><p>Évacuer l’eau de pluie correctement</p><p>Protéger vos murs, vos fondations et vos avancées, quel soit en bois ou en pvc.</p><p>Prolonger la durée de vie de votre maison</p><p>Quel que soit le modèle choisit, elles vous serviront au quotidien.</p><h4>Le zinc : Le choix du long terme</h4><p>Ses points forts :</p><p>Une durée de vie fiable dès l’instant où la pose est réalisée dans les règles de l’art</p><p>Une résistance efficace contre le froid, la chaleur et la grêle</p><p>Une étanchéité optimale grâce aux soudures renforcées et au joint de dilatation</p><p>Un matériau 100 % recyclable</p><h4>Le PVC : Un prix séduisant</h4><p>Ses avantages :</p><p>Coût plus accessible</p><p>Pose rapide</p><p>Léger et facile à installer</p><p>Plusieurs coloris disponibles</p><p>C’est une solution souvent choisie pour des projets à court ou moyen terme.</p><h4>Là où le PVC montre ses limites</h4><p>Avec le temps, le PVC peut :</p><p>Se fragiliser à cause du gel et de la grêle</p><p>Se déformer</p><p>Les raccords d’étanchéité (talon, jonction, naissance) peuvent perdre en efficacité dans le temps</p><p>Donner un rendu plus “standard”</p><h4>Zinc ou PVC : le comparatif sans détour</h4><p>Critère</p><p>Zinc</p><p>PVC</p><p>Durée de vie</p><p>Très longue</p><p>Moyenne</p><p>Prix</p><p>Elevé</p><p>Modéré</p><p>Résistance</p><p>Excellente</p><p>Correcte</p><p>Étanchéité</p><p>Soudée, fiable</p><p>Raccords plus sensibles</p><p>Esthétique</p><p>Haut de gamme</p><p>Basique</p><p>Entretien</p><p>Très faible</p><p>Régulier</p><p>Chez AERTOIT, on le dit souvent :</p><p>👉 le zinc coûte plus cher à poser, mais demande peu d’entretien.</p><h4>Une pose réussie fait toute la différence</h4><p>Que vous choisissiez des descentes d’eaux pluviales en zinc ou en pvc, la pose et le respect des normes est primordiales.</p><p>Nos équipes assurent :</p><p>Un travail pensé pour durer efficacement</p><p>Des développés de gouttières adaptés à la surface de votre toit</p><p>Des soudures propres et étanches ainsi que des joints de dilatation</p><h4>AERTOIT, des choix clairs pour une toiture sereine</h4><p>Vous hésitez ? C’est normal.</p><p>Mais une chose est sûre : mieux vaut décider avec un expert qu’être déçu plus tard.</p><p>Chez AERTOIT, on vous conseille honnêtement, on pose proprement, et on pense long terme.</p><p>👉 Contactez-nous pour un diagnostic et un devis personnalisé.</p><p>Votre toiture vous dira merci.</p>' WHERE `slug` = 'gouttieres-en-zinc-ou-pvc-que-choisir';
UPDATE `blog_posts` SET `body` = '<p>Quand l’hiver arrive, votre toiture passe en mode étanchéité du froid, du vent et de la pluie.</p><p>Entre les infiltrations, les pertes de chaleur et les dégradations invisibles, c’est souvent pendant les premiers gros épisodes pluvieux que les problèmes se révèlent, mais à ce moment-là, il est déjà trop tard.</p><p>La bonne nouvelle ? Avec une inspection et quelques vérifications clés, vous pouvez éviter 95 % des dégâts hivernaux.</p><p>Et croyez-nous : votre facture de chauffage et vos murs vous diront merci ainsi que votre assureur.</p><h4>Vérifier l’isolation thermique : votre meilleur allié contre le froid (et les dépenses inutiles)</h4><p>Une toiture mal isolée, c’est une vraie passoire énergétique.</p><p>Jusqu’à 30 % des pertes de chaleur s’échappent par le toit. Résultat : vous chauffez plus, vous payez plus, et votre maison reste froide malgré les radiateurs à fond.</p><p>Pour un hiver confortable, on vérifie :</p><p>L’état de l’isolant existant comme la laine de roche, laine de verre…</p><p>L’absence d’humidité dans les combles</p><p>La continuité de l’isolation pour éviter les ponts thermiques</p><p>L’épaisseur et la performance réelle du matériau</p><p>Une isolation en bon état vous garantit :</p><p>✔ un meilleur confort thermique</p><p>✔ une réduction significative de vos factures</p><p>✔ une maison qui garde la chaleur même en plein mois de janvier</p><h4>Contrôler les points sensibles : les zones où les infiltrations adorent se cacher</h4><p>Chaque hiver, chez AERTOIT, on voit les mêmes scénarios : les infiltrations ne viennent presque jamais en plein carré du toit… mais des zones sensibles, tels que les raccords de toiture qui fatiguent avec le temps.</p><p>À inspecter absolument :</p><p>Les cheminées</p><p>C’est l’un des premiers points faibles. Un solin mal scellé ou fatigué peut laisser passer l’eau par capillarité. Et là… bonjour les tâches au plafond.</p><p>Les fenêtres de toit (VELUX)</p><p>Joint usé, raccord défaillant, mauvais écoulement des eaux : en hiver, le moindre défaut devient un cauchemar.</p><p>Les raccords en zinc</p><p>Autour des rives, noues, gouttières ou ventilations. Le zinc est résistant, mais les fixations et les jonctions peuvent bouger dans le temps.</p><p>Les gouttières</p><p>Une gouttière bouchée en automne = une infiltration garantie en hiver. Les débordements d’eau créent humidité, mousses, dégradations de façade… et parfois même des infiltrations dans les murs.</p><p>Ces zones doivent être vérifiées, ajustées ou réparées avant l’arrivée des pluies hivernales.</p><h4>Un toit bien étanche : la condition n°1 pour passer l’hiver sans dégâts</h4><p>Une toiture étanche, ce n’est pas juste “important”. C’est vital.</p><p>Pourquoi ?</p><p>Parce qu’une infiltration hivernale ne se voit pas tout de suite. Elle peut progresser derrière les murs, imbiber l’isolation, détériorer la charpente… Et lorsqu’on voit la tâche au plafond, c’est souvent que le problème existe depuis des semaines voir plus.</p><p>Une toiture bien étanche, c’est :</p><p>✔ la garantie d’éviter les moisissures et l’humidité</p><p>✔ la protection de votre isolation thermique</p><p>✔ la préservation de votre charpente</p><p>✔ la tranquillité d’esprit tout l’hiver</p><h4>Aertoit, votre partenaire pour passer l’hiver sereinement</h4><p>L’hiver n’attend pas. Et une toiture qui n’est pas prête… non plus.</p><p>Chez Aertoit, nous réalisons :</p><p>des inspections pré-hivernales complètes</p><p>des vérifications d’isolation</p><p>le contrôle des points sensibles (cheminées, VELUX, zinc)</p><p>le nettoyage des gouttières</p><p>des réparations et ajustements rapides</p><p>un diagnostic offert avant travaux</p><p>Notre objectif ?</p><p>Que vous passiez l’hiver au chaud et au sec, sans stress et sans mauvaises surprises.</p><p>Vous souhaitez contrôler votre toiture avant les pluies hivernales ?</p><p>Contactez Aertoit dès maintenant pour un diagnostic gratuit.</p><p>Un hiver serein commence toujours par un toit en bonne santé.</p>' WHERE `slug` = 'anticiper-hiver-preparer-sa-toiture';
UPDATE `blog_posts` SET `body` = '<p>Chez AERTOIT, nous avons constaté, chaque année une augmentation des demandes d’intervention pour des gouttières bouchées à cette période.</p><h4>Pourquoi nettoyer ses gouttières pendant la saison de l’automne particulièrement ?</h4><p>Les gouttières jouent un rôle clé dans la protection de votre maison en évacuant l’eau de pluie du toit vers le sol. Mais en automne, les feuilles, brindilles et autres débris s’accumulent rapidement, obstruant ces conduits essentiels. Une gouttière bouchée, c’est la porte ouverte à de nombreux problèmes :</p><p>Infiltrations d’eau : L’eau stagnante peut s’infiltrer dans les murs selon le modèle de gouttières, les fondations ou même le toit, causant une présence d’humidité et des dégâts coûteux.</p><p>Dommages structurels : Une gouttière en zinc ou en pvc pleine peut se déssouder ou se détacher sous le poids des débris, entraînant des réparations.</p><p>Problèmes esthétiques : Les débordements d’eau peuvent tacher vos façades ou abîmer vos aménagements extérieurs.</p><p>Une de nos clients nous a récemment raconté comment une gouttière obstruée a provoqué une fuite dans son salon après une forte pluie. Le coût des réparations a largement dépassé celui d’un simple nettoyage. Moralité : mieux vaut prévenir que guérir !</p><h4>À quelle fréquence nettoyer ses gouttières ?</h4><p>La fréquence dépend de votre environnement et de la saison. Voici nos recommandations pour un entretien optimal :</p><p>En automne, une à deux fois : Avec la chute des feuilles, un nettoyage en début et en fin de saison est souvent nécessaire, surtout si vous êtes entourés d’arbres.</p><p>Au printemps : Éliminez les débris accumulés pendant l’hiver pour préparer vos gouttières aux pluies printanières.</p><p>En ville : Une fois par an peut suffire, car les débris sont moins nombreux, mais restez vigilant si vous remarquez un mauvais écoulement.</p><p>Un signe que vos gouttières ont besoin d’attention ? Si l’eau déborde ou ne s’écoule pas correctement lors d’une averse, il est temps d’agir.</p><h4>Les étapes pour un nettoyage réussi</h4><p>Voici notre méthode éprouvée pour nettoyer vos gouttières efficacement :</p><p>Préparez votre matériel : Rassemblez vos outils ainsi que vos EPI et assurez-vous d’avoir une échelle stable si nécessaire.</p><p>Retirez les gros débris : À l’aide d’une pelle ou de vos mains protégées, enlevez les feuilles et les brindilles accumulées.</p><p>Rincez à l’eau : Utilisez un jet d’eau pour nettoyer les résidus restants et vérifier que l’eau s’écoule librement.</p><p>Vérifiez l’état des gouttières et des descentes : Profitez du nettoyage pour repérer d’éventuelles fissures ou fixations desserrées, et contactez un professionnel si nécessaire.</p><h4>Quand faire appel à un professionnel ?</h4><p>Nettoyer ses gouttières soi-même est réalisable, mais cela peut devenir risqué ou chronophage, surtout si votre maison est à plusieurs étages ou si les gouttières sont en mauvais état. Chez AERTOIT, nous proposons des services de nettoyage et d’entretien de gouttières avec des équipements professionnels. Nos équipes travaillent en toute sécurité et s’assurent que vos gouttières fonctionnent parfaitement. Un petit investissement aujourd’hui peut vous éviter des réparations coûteuses demain.</p><h4>Les avantages d’un entretien régulier</h4><p>Un nettoyage régulier de vos gouttières, c’est comme un check-up pour votre maison. Voici ce que vous y gagnez :</p><p>Protection contre les infiltrations : Vous préservez vos murs, vos fondations et votre toiture.</p><p>Économies à long terme Évitez les réparations coûteuses causées par des gouttières endommagées.</p><p>Tranquillité d’esprit : Une gouttière propre, c’est l’assurance que votre maison est prête à affronter les intempéries.</p><h4>Contactez AERTOIT pour un entretien professionnel</h4><p>L’automne est là, et les feuilles ne vont pas attendre. Si vous souhaitez confier l’entretien de vos gouttières à des experts, contactez AERTOIT. Nous intervenons rapidement pour nettoyer, inspecter et réparer vos gouttières, tout en vous garantissant un travail soigné et sécurisé.</p>' WHERE `slug` = 'nettoyage-de-gouttieres-l-essentiel-de-l-automne';
UPDATE `blog_posts` SET `body` = '<h4>Introduction</h4><p>Le retour des beaux jours annonce le moment idéal pour prendre soin de votre toiture, notamment en effectuant un démoussage complet. Mais pourquoi est-il important de démousser régulièrement votre toiture, et comment le faire correctement ? On vous explique tout en détail.</p><h4>Pourquoi réaliser régulièrement un démoussage de toiture ?</h4><p>Avec le temps, votre toiture subit les effets des intempéries : pluie, vent, humidité, gel et dégel, qui entraînent l''apparition de mousses, lichens sur vos tuiles, ardoises ou bacs acier.</p><p>Ces végétaux provoquent plusieurs problèmes :</p><p>Ils retiennent l’humidité et accélèrent la détérioration des matériaux de couverture.</p><p>Ils peuvent créer des infiltrations et des dégâts d’eau.</p><p>Un démoussage régulier permet donc de prolonger la durée de vie de votre couverture et de préserver l’état général de votre toiture.</p><h4>À quel moment faut-il démousser votre toiture ?</h4><p>Le printemps est la période idéale pour réaliser un démoussage. Les conditions climatiques douces assurent un séchage optimal, facilitant ainsi l''application des traitements nécessaires.</p><p>Il est conseillé de réaliser cette opération :</p><p>Tous les 4 à 6 ans pour les toitures en bon état.</p><p>Tous les 2 ans pour les toitures plus âgées ou fortement exposées aux végétations.</p><h4>Comment se déroule un démoussage professionnel ?</h4><p>Chez Aertoit Couverture, nous procédons par étapes pour garantir un résultat efficace et durable :</p><p>1. Diagnostic de la toiture</p><p>Nos couvreurs examinent votre toiture afin de détecter les éventuels problèmes (tuiles abîmées, fissures, infiltrations).</p><p>2. Nettoyage approfondi</p><p>Nous éliminons mousses, lichens et autres végétaux par un nettoyage manuel ou à basse pression afin de ne pas abîmer les matériaux.</p><p>3. Application d’un produit anti-mousse professionnel</p><p>Un traitement préventif anti-mousse est appliqué sur l’ensemble de la toiture. Ce produit limite durablement la réapparition des végétaux.</p><h4>Pourquoi faire appel à un professionnel comme Aertoit Couverture ?</h4><p>Faire intervenir un professionnel garantit :</p><p>Une inspection précise et détaillée de votre toiture.</p><p>L''utilisation de produits efficaces, respectueux de vos matériaux et de l''environnement.</p><p>Une intervention sécurisée, réalisée par des spécialistes expérimentés.</p><h4>Conclusion : ne négligez pas l’entretien de votre toiture !</h4><p>Un démoussage régulier est essentiel pour assurer la pérennité de votre toiture et préserver la valeur de votre bien immobilier. N''attendez pas qu''il soit trop tard pour prendre soin de votre couverture.</p><p>Pour toute question ou demande de devis gratuit, n’hésitez pas à nous contacter directement. Nos équipes se feront un plaisir de vous accompagner dans l''entretien de votre toiture.</p>' WHERE `slug` = 'la-saison-du-demoussage-est-arrivee';
UPDATE `blog_posts` SET `body` = '<h4>Introduction</h4><p>Choisir la bonne isolation pour votre toiture est une décision essentielle qui impacte non seulement le confort de votre maison, mais aussi vos économies d’énergie et l’empreinte écologique de votre habitat. Dans cet article, nous passons en revue les principales solutions d’isolation de toiture disponibles, afin de vous aider à faire le meilleur choix en fonction de votre budget, de vos besoins et des contraintes de votre habitation.</p><h4>1. Pourquoi bien isoler sa toiture ?</h4><p>Limiter les pertes de chaleur :Une isolation performante réduit considérablement les déperditions de chaleur. Dans une maison mal isolée, jusqu’à 30 % de l’énergie peut être perdue, entraînant une hausse des factures de chauffage.</p><p>Améliorer le confort thermique :Une bonne isolation maintient une température intérieure agréable en hiver comme en été, garantissant un confort optimal à tous les occupants.</p><p>Réaliser des économies d’énergie :En diminuant les pertes de chaleur, vous réduisez votre consommation énergétique, ce qui se traduit par des économies sur le long terme.</p><p>Adopter une démarche écologique :Moins d’énergie consommée signifie une réduction de l’empreinte carbone de votre maison.</p><p>Valoriser votre bien immobilier :Un logement bien isolé bénéficie d’un meilleur diagnostic de performance énergétique (DPE) et a une valeur de revente potentiellement plus élevée.</p><h4>2. Les critères pour choisir la bonne isolation de toiture</h4><p>Type de toiture</p><p>Toiture inclinée : Que ce soit pour des combles aménagés ou perdus, l’isolation doit être adaptée aux pentes du toit.</p><p>Toiture plate ou toit-terrasse : Ces toitures demandent des techniques d’isolation spécifiques pour gérer l’écoulement des eaux.</p><p>Méthodes d’isolation</p><p>Isolation des combles perdus : Moins coûteuse et plus rapide à mettre en œuvre, elle rend l''espace inhabitable en un lieu de stockage éventuel.</p><p>Isolation par l’extérieur (Sarking) : Bien que plus onéreuse, elle offre une isolation supérieure et préserve l’espace intérieur.</p><p>Performance thermique</p><p>La performance d’un isolant se mesure en résistance thermique (R), exprimée en m².K/W. En sur toiture, une résistance supérieure à 6 m².K/W est recommandée. (Résistance minimale pour obtenir les aides)</p><p>Autres critères</p><p>Isolation phonique : Essentielle dans les zones urbaines ou proches de sources de bruit.</p><p>Résistance au feu : Un critère crucial pour la sécurité.La laine de verre ainsi que la laine de roche sont les matériaux qui résistent le mieux au feu.</p><p>Écologie et durabilité : Privilégiez les matériaux biosourcés si l’impact environnemental est une priorité.</p><h4>3. Comparatif des solutions d’isolation pour toiture</h4><p>Type d''isolant</p><p>Avantages</p><p>Inconvénients</p><p>Laine de verre</p><p>Bon marché, bonne isolation thermique et phonique</p><p>Sensible à l’humidité</p><p>Laine de roche</p><p>Retardateur, bonne isolation acoustique</p><p>Fibre de bois</p><p>Écologique, excellent déphasage thermique (idéal contre la chaleur)</p><p>Coût plus élevé, matériau plus épais.</p><p>Polyuréthane (Sarking)</p><p>Très performant thermiquement.</p><p>Moins écologique, plus épais.</p><p>Isolant mince (Actis)</p><p>Facile à poser, solution innovante en multicouches, faible épaisseur</p><p>Déphasage thermique modéré</p><h4>4. Quelle solution choisir selon votre situation ?</h4><p>En fonction de votre budget</p><p>Petit budget : La laine de verre ou la laine de roche représentent des solutions économiques tout en offrant une bonne isolation.</p><p>Budget moyen : Le Sarking en polyuréthane, malgré son coût, garantit une isolation de haute performance grâce à sa faible épaisseur et sa légèreté.</p><p>Budget élevé : Le Sarking en fibre de bois offre un compromis entre performance et écologie.</p><p>Selon vos besoins spécifiques</p><p>Isolation thermique et phonique optimale : La fibre de bois est excellente dans ce domaine.</p><p>Solution écologique : La fibre de bois, issue de forêts gérées durablement, est un choix judicieux.</p><p>Optimisation de l’espace et performance thermique : La méthode Sarking et sa pose par l’extérieur permet de gagner en espace tout en offrant une excellente isolation.</p><p>Selon le type de travaux</p><p>Rénovation extérieure : L’option sarking est idéale pour une isolation par l’extérieur.</p><p>Combles perdus : Le soufflage de laine de roche ou en fibre de bois peut être une solution efficace.</p><h4>Conclusion</h4><p>Il n’existe pas de solution universelle pour l’isolation de toiture. Le choix dépend de nombreux facteurs, dont votre budget, la configuration de votre maison et vos priorités en termes de confort, d’écologie et de performance énergétique. Pour déterminer la meilleure solution, il est fortement recommandé de faire appel à un couvreur professionnel pour réaliser un diagnostic thermique complet.</p><p>AERTOIT se tient à votre disposition pour vous conseiller et vous accompagner dans votre projet d’isolation. N’hésitez pas à nous contacter pour obtenir un devis personnalisé et découvrir la solution qui correspond le mieux à vos besoins.</p>' WHERE `slug` = 'quelle-est-la-meilleure-isolation-pour-votre-toiture';
UPDATE `blog_posts` SET `body` = '<h4>Introduction</h4><p>Le choix du matériau de couverture est une décision clé pour tout propriétaire souhaitant rénover ou construire sa maison. Dans le Val-de-Marne, où le climat est tempéré avec des épisodes de pluie et de vent, il est essentiel d’opter pour une toiture résistante, durable et adaptée à votre budget. Tuiles, ardoises, zinc, bac acier… Chaque matériau a ses spécificités. Cet article vous guide pour faire le meilleur choix en fonction de vos besoins et des contraintes locales.</p><h4>1. Les critères essentiels pour choisir sa toiture</h4><p>Avant de vous lancer, voici les principaux critères à prendre en compte :</p><p>• La réglementation locale : Le PLU (Plan Local d’Urbanisme) peut imposer certains matériaux selon votre zone d’habitation.</p><p>• L’isolation thermique et phonique : Une toiture bien isolée réduit les pertes de chaleur et améliore le confort intérieur.</p><p>• La résistance aux intempéries : Pluie, vent, gel… Le matériau doit être adapté au climat du Val-de-Marne.</p><p>• L’entretien : Certains revêtements nécessitent un entretien régulier (nettoyage, traitement anti-mousse).</p><p>• Le budget : Le coût varie selon le matériau et la complexité de la pose.</p><p>• L’aspect technique : Il est impératif de prendre en considération la pente d’une toiture en adoptant les bons matériaux</p><h4>2. Comparatif des principaux matériaux de toiture</h4><p>Les tuiles : robustesse et esthétique traditionnelle</p><p>✅ Avantages :</p><p>• Excellente durée de vie (minimum 50 ans)</p><p>• Bonne isolation thermique et phonique</p><p>• Esthétique adaptée aux maisons traditionnelles</p><p>❌ Inconvénients :</p><p>• Poids important nécessitant une charpente fiable</p><p>• Pose plus coûteuse que certains matériaux</p><p>👉 Idéal pour : Les propriétaires souhaitant une toiture durable et esthétique, conforme aux exigences architecturales locales.</p><p>L’ardoise : élégance et longévité exceptionnelle</p><p>• Matériau haut de gamme très esthétique</p><p>• Durée de vie exceptionnelle (jusqu’à 100 ans)</p><p>• Très résistant aux intempéries et au feu</p><p>• Coût élevé</p><p>• Pose délicate nécessitant un artisan qualifié</p><p>👉 Idéal pour : Ceux qui recherchent une toiture élégante et durable, malgré un investissement initial plus important.</p><p>Le zinc : légèreté et modernité</p><p>• Léger et facile à poser</p><p>• Grande résistance aux intempéries</p><p>• Peu d’entretien nécessaire</p><p>• Isolation thermique limitée</p><p>• Prix plus élevé que les tuiles classiques</p><p>👉 Idéal pour : Les maisons contemporaines et les propriétaires cherchant un matériau léger et moderne.</p><p>Le bac acier : Rapide à poser et de nombreux choix de couleurs</p><p>• Prix attractif</p><p>• Facilité et rapidité de pose</p><p>• Bonne résistance aux intempéries</p><p>• Peu esthétique</p><p>• Prix variable selon différents critères</p><p>👉 Idéal pour : Les extensions, garages, et toitures secondaires nécessitant une solution économique et rapide.</p><h4>3. Quel matériau choisir selon votre situation ?</h4><p>• Vous recherchez une toiture traditionnelle et durable ? Optez pour les tuiles ou l’ardoise.</p><p>• Vous privilégiez un matériau léger et moderne ? Le zinc est une excellente alternative.</p><p>• Vous avez un budget serré ? Le bac acier est le plus économique, mais moins isolant selon l’épaisseur d’isolation choisie.</p><p>• Vous voulez une toiture écologique ? Pensez aux tuiles en terre cuite naturelles ou aux toitures végétalisées.</p><h4>4. Faire appel à un professionnel pour un choix adapté</h4><p>Choisir le bon matériau ne se fait pas au hasard. Un couvreur expérimenté, comme Aertoit, vous conseille en fonction des contraintes de votre maison et des normes en vigueur dans le Val-de-Marne.</p><p>Nous vous accompagnons dans votre projet de toiture en vous proposant les meilleures solutions adaptées à votre budget et à vos besoins. Contactez-nous dès aujourd’hui pour un devis personnalisé !</p><h4>Conclusion</h4><p>Le choix du matériau de toiture est un investissement à long terme qui influence l’esthétique, la durabilité et l’isolation de votre maison. En tenant compte de vos priorités et des contraintes locales, vous trouverez la solution idéale pour votre habitat.</p><p>Besoin d’un conseil sur mesure ? Aertoit est à votre disposition pour répondre à toutes vos questions et vous accompagner dans votre projet !</p>' WHERE `slug` = 'comment-choisir-le-bon-materiau-pour-votre-toiture';
UPDATE `pages` SET `body` = '<p>Découvrez une équipe de professionnels de la toiture à votre service !</p><h2>Qui sommes-nous ?</h2><p>Depuis plus de 20 ans, Aertoit Couverture est votre partenaire de confiance pour tous vos besoins en toiture. Basés à l''Haÿ-Les-Roses, nous mettons notre expertise et notre passion au service de la protection et de la beauté de votre maison.</p><p>Certifié RGE QUALIBAT</p><p>+25 Salairés Qualifiés</p><p>Installateur Pro VELUX</p><p>+ 3000 Projets Réalisés</p><p>Adhérent FFB</p><p>Démarche RSE</p><h4>Écoute et Conseils</h4><p>Nos couvreurs experts sont à votre écoute pour vous offrir des solutions personnalisées et adaptées à vos besoins.</p><h4>Excellence</h4><p>Nous mettons un point d''honneur à garantir une qualité irréprochable et une propreté méticuleuse sur chaque projet.</p><h4>Satifaction Client</h4><p>Votre satisfaction est notre priorité absolue, nous travaillons sans relâche pour vous offrir une expérience exceptionnelle.</p><h2>Rencontrez Nos Experts</h2><p>Yoann et son Équipe</p><p>Couvreur / Charpentier</p><p>Thomas et son Équipe</p><p>Couvreur / Zingueur</p><p>Nicolas et son Équipe</p><p>Couvreur / Charpentier / Ardoisier</p><p>Gérald et son Équipe</p><p>Couvreur / Ardoisier / Zingueur</p><p>Juan & Nils</p><p>Patrice & Ilyes</p><h2>Vous Souhaitez Nous Rejoindre ?</h2><p>Aertoit Couverture recrute des talents ! Découvrez les offres d''emploi disponnibles et postulez dès maintenant !</p><p>Chef(fe) d''Équipe</p><p>📍 94240 Val-de-Marne</p><p>📄 CDI</p><p>🕐 Temps Plein</p><p>💸 2300 - 2900 € net / mois + primes</p><p>🎓 CAP / BP ou autres</p><p>💼 ≥ 10 ans</p><p>Couvreur/euse Qualifié(e)</p><p>📍 94240 L''Haÿ-les-Roses</p><p>📄 CDD avec possibilité de CDI</p><p>💸 1900 - 2400€ net / mois + primes</p><p>💼 ≥ 5 ans</p>' WHERE `slug` = 'a-propos';

SELECT 'contaminated' AS check_name, COUNT(*) AS rows_affected FROM (
  SELECT slug FROM services   WHERE body LIKE '%Rue des Jardins%' OR body LIKE '%contact@aertoit%' OR body LIKE '%Appellez%'
  UNION ALL SELECT slug FROM blog_posts  WHERE body LIKE '%Rue des Jardins%' OR body LIKE '%contact@aertoit%' OR body LIKE '%Appellez%'
  UNION ALL SELECT slug FROM job_postings WHERE body LIKE '%Rue des Jardins%' OR body LIKE '%contact@aertoit%' OR body LIKE '%Appellez%'
  UNION ALL SELECT slug FROM pages       WHERE body LIKE '%Rue des Jardins%' OR body LIKE '%contact@aertoit%' OR body LIKE '%Appellez%'
) x;
